def pricing_html() -> str:
    return ('''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Lucas plans for secure AI-to-computer execution. Start free and upgrade when you need more Operations, Computers, or AI connections."><link rel="canonical" href="https://lucasmcp.com/pricing"><link rel="icon" type="image/png" sizes="32x32" href="/assets/lucas-logo-square.png?v=20260908"><link rel="shortcut icon" type="image/png" href="/assets/lucas-logo-square.png?v=20260908"><title>Lucas Pricing</title><style>*{box-sizing:border-box}body{margin:0;background:#05070d;color:#f5f7ff;font:15px/1.6 Inter,system-ui,-apple-system,Segoe UI,sans-serif}a{color:inherit;text-decoration:none}.wrap{max-width:1180px;margin:auto;padding:0 28px 72px}.nav{height:82px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.08)}.nav img{width:190px;height:50px;object-fit:contain;object-position:left center}.nav-actions{display:flex;gap:10px}.ghost,.primary{display:inline-flex;align-items:center;justify-content:center;min-height:42px;padding:0 16px;border-radius:10px;font-weight:750}.ghost{border:1px solid rgba(255,255,255,.13);color:#d8deed;background:rgba(255,255,255,.035)}.primary{background:linear-gradient(110deg,#6473f4,#5969e9);color:#fff;box-shadow:0 12px 36px rgba(86,103,235,.2)}.hero{text-align:center;padding:86px 0 52px}.eyebrow{display:inline-block;font-size:11px;font-weight:800;letter-spacing:.17em;color:#8a96b0}.hero h1{font-size:clamp(46px,6vw,76px);line-height:1;letter-spacing:-.055em;margin:18px 0}.hero p{max-width:680px;margin:0 auto;color:#99a4bb;font-size:18px}.billing-toggle{display:flex;justify-content:center;gap:4px;margin:0 auto 34px;padding:4px;width:max-content;border:1px solid rgba(255,255,255,.12);border-radius:12px;background:rgba(255,255,255,.04)}.billing-toggle button{border:0;border-radius:9px;padding:9px 16px;background:transparent;color:#9aa4bb;font-weight:750;cursor:pointer}.billing-toggle button.active{background:#fff;color:#111827}.save{font-size:11px;color:#70dfa9;margin-left:5px}.plans{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.card{position:relative;background:linear-gradient(180deg,rgba(16,21,34,.96),rgba(9,12,21,.96));border:1px solid rgba(255,255,255,.1);border-radius:18px;padding:28px;min-height:430px;display:flex;flex-direction:column}.card.hot{border-color:#6d7cff;box-shadow:0 0 0 1px rgba(109,124,255,.2),0 26px 70px rgba(65,79,195,.16)}.tag{position:absolute;right:18px;top:18px;font-size:10px;letter-spacing:.1em;color:#bfc7ff;border:1px solid rgba(109,124,255,.4);padding:5px 8px;border-radius:999px;background:rgba(109,124,255,.09)}.plan{font-size:24px;font-weight:800}.price{font-size:42px;font-weight:850;letter-spacing:-.04em;margin:12px 0 5px}.price small{font-size:14px;color:#8e99b0;font-weight:650}.desc{color:#8f9ab1;min-height:50px}.features{list-style:none;padding:0;margin:20px 0 28px;display:grid;gap:11px;color:#d8deea}.features li:before{content:'✓';color:#70dfa9;margin-right:9px}.card .primary,.card .ghost{margin-top:auto;width:100%}.expansion{margin-top:20px;padding:26px 28px;border:1px solid rgba(255,255,255,.1);border-radius:18px;background:linear-gradient(110deg,rgba(95,109,240,.12),rgba(46,176,220,.06));display:grid;grid-template-columns:1fr auto;align-items:center;gap:24px}.expansion h2{margin:0 0 6px;font-size:24px}.expansion p{margin:0;color:#98a3b9}.expansion strong{font-size:28px}.note{text-align:center;color:#7f8aa1;font-size:13px;margin-top:24px}.faq{margin-top:72px}.faq h2{text-align:center;font-size:34px}.faq-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.faq-item{padding:20px;border-top:1px solid rgba(255,255,255,.1);color:#919cb2}.faq-item b{display:block;color:#eef1f8;margin-bottom:8px}@media(max-width:820px){.plans,.faq-grid{grid-template-columns:1fr}.expansion{grid-template-columns:1fr}.nav-actions .ghost{display:none}.hero{padding-top:58px}.card{min-height:0}}</style></head><body><div class="wrap"><nav class="nav"><a href="/"><img src="/assets/lucas-logo-horizontal-white.png" alt="Lucas"></a><div class="nav-actions"><a class="ghost" href="/">Home</a><a class="primary" href="/dashboard">Open Dashboard</a></div></nav><section class="hero"><div class="eyebrow">SIMPLE, PREDICTABLE PRICING</div><h1>Start free. Scale when you need it.</h1><p>One Lucas account is for one person. Choose the plan that fits your workload, then expand Pro+ without changing your setup.</p></section><div class="billing-toggle"><button id="monthlyBtn" class="active" onclick="setPricingInterval('month')">Monthly</button><button id="annualBtn" onclick="setPricingInterval('year')">Annual <span class="save">Save ~17%</span></button></div><section class="plans"><article class="card"><div class="plan">Free</div><div class="price">$0</div><p class="desc">For trying Lucas and light personal workflows.</p><ul class="features"><li>1,000 Operations / month</li><li>1 Computer</li><li>1 AI account</li><li>Core Lucas execution</li></ul><a class="ghost" href="/dashboard">Get started</a></article><article class="card"><div class="plan">Pro</div><div class="price"><span id="proPrice">$9.99</span> <small id="proPeriod">/ month</small></div><p class="desc">For regular personal automation on multiple computers.</p><ul class="features"><li>25,000 Operations / month</li><li>3 Computers</li><li>1 AI account</li><li>Full Lucas execution</li></ul><a class="primary" id="proLink" href="/billing?select=pro&interval=month">Choose Pro</a></article><article class="card hot"><span class="tag">BEST VALUE</span><div class="plan">Pro+</div><div class="price"><span id="proPlusPrice">$19.99</span> <small id="proPlusPeriod">/ month</small></div><p class="desc">For heavier workflows and users who need expandable capacity.</p><ul class="features"><li>100,000 Operations / month</li><li>6 Computers</li><li>3 AI accounts</li><li>Expansion Pack access</li></ul><a class="primary" id="proPlusLink" href="/billing?select=pro_plus&interval=month">Choose Pro+</a></article></section><section class="expansion"><div><h2>Expansion Pack</h2><p>Pro+ only · +100,000 Operations · +6 Computers · +1 AI account per pack</p></div><strong><span id="expansionPrice">$14.99</span> <small id="expansionPeriod">/ month</small></strong></section><p class="note">Each actual Lucas computer tool operation counts as one Operation. Heartbeats, reconnects, dashboard refreshes, authentication, and internal checks do not consume Operations.</p><section class="faq"><h2>Good to know</h2><div class="faq-grid"><div class="faq-item"><b>Can I share one account?</b>No. One Lucas account is intended for one person.</div><div class="faq-item"><b>Who can buy Expansion Packs?</b>Expansion Packs are available only to Pro+ subscribers.</div><div class="faq-item"><b>What happens at the limit?</b>Your data stays intact. Upgrade or add capacity to continue new billable operations.</div></div></section></div><script>function setPricingInterval(i){const y=i==='year';document.getElementById('monthlyBtn').classList.toggle('active',!y);document.getElementById('annualBtn').classList.toggle('active',y);document.getElementById('proPrice').textContent=y?'$99.99':'$9.99';document.getElementById('proPeriod').textContent=y?'/ year':'/ month';document.getElementById('proPlusPrice').textContent=y?'$199.99':'$19.99';document.getElementById('proPlusPeriod').textContent=y?'/ year':'/ month';document.getElementById('expansionPrice').textContent=y?'$149.99':'$14.99';document.getElementById('expansionPeriod').textContent=y?'/ year':'/ month';document.getElementById('proLink').href='/billing?select=pro&interval='+i;document.getElementById('proPlusLink').href='/billing?select=pro_plus&interval='+i}const q=new URLSearchParams(location.search);if(q.get('interval')==='year')setPricingInterval('year');</script></body></html>''').replace('<head>', '<head>'+META_PIXEL_HEAD, 1)


def dashboard_billing_html() -> str:
    return '''<div id="billing" class="view hidden"><style>#billing .billing-plans{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin-bottom:18px}#billing .billing-plan-card{position:relative;min-height:365px;padding:26px;border:1px solid #e2e8f0;border-radius:18px;background:linear-gradient(180deg,#fff,#fbfcff);display:flex;flex-direction:column;box-shadow:0 10px 28px rgba(15,23,42,.045)}#billing .billing-plan-card.is-featured{border-color:#9db8ff;background:linear-gradient(180deg,#fff,#f7f9ff)}#billing .billing-plan-tag{position:absolute;right:18px;top:18px;padding:5px 9px;border-radius:999px;background:#eef3ff;color:#3157d5;font-size:10px;font-weight:800;letter-spacing:.08em}#billing .billing-plan-name{font-size:24px;font-weight:800;color:#101828}#billing .billing-plan-price{font-size:38px;line-height:1.1;font-weight:850;letter-spacing:-.04em;color:#101828;margin:12px 0 8px}#billing .billing-plan-price small{font-size:14px;font-weight:650;color:#667085}#billing .billing-plan-desc{min-height:48px;margin:0;color:#667085}#billing .billing-plan-features{list-style:none;padding:0;margin:20px 0 26px;display:grid;gap:10px;color:#344054}#billing .billing-plan-features li:before{content:'✓';color:#12b76a;font-weight:800;margin-right:9px}#billing .billing-plan-card .btn{margin-top:auto;width:100%;min-height:42px}#billing .billing-expansion-card,#billing .billing-payment-card{border-radius:18px}#billing .billing-expansion-card{border:1px solid #dbe4ff;background:linear-gradient(110deg,#f8faff,#f3fbff)}#billing .billing-payment-card{margin-top:16px;display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap}@media(max-width:900px){#billing .billing-plans{grid-template-columns:1fr}#billing .billing-plan-card{min-height:0}}</style><div class="top"><div><h2>Plan & Billing</h2><p class="muted">Manage your Lucas plan, usage limits, and billing.</p></div></div><div id="billingNotice" class="card hidden" style="margin-bottom:16px"></div><div id="billingError" class="error hidden"></div><div class="card" style="margin-bottom:16px"><div style="display:flex;justify-content:space-between;align-items:center;gap:14px;flex-wrap:wrap"><div><div class="muted">Current plan</div><div id="billingPlan" class="metric">Loading…</div><div id="billingRenew" class="muted"></div></div><div id="billingPrice" style="font-size:22px;font-weight:750"></div></div></div><div class="grid" style="margin-bottom:22px"><div class="card"><div class="muted">Operations</div><div id="billingRequests" class="metric">—</div><div id="billingRequestsBar" style="height:7px;background:#eef1f5;border-radius:999px;margin-top:12px;overflow:hidden"><i style="display:block;height:100%;width:0;background:#155eef"></i></div></div><div class="card"><div class="muted">Computers</div><div id="billingComputers" class="metric">—</div></div><div class="card"><div class="muted">AI accounts</div><div id="billingAi" class="metric">—</div></div></div><div class="top" style="margin-bottom:14px"><div><h3 style="margin-bottom:4px">Plans</h3><div class="muted">Pay monthly at regular price, or annually and save ~17%.</div></div><div class="billing-cycle-toggle"><button id="billingCycleMonth" class="btn secondary" onclick="billingSetInterval('month')">Monthly</button><button id="billingCycleYear" class="btn secondary" onclick="billingSetInterval('year')">Annual · Save ~17%</button></div></div><div class="billing-plans"><div id="billingCardFree" class="billing-plan-card"><div class="billing-plan-name">Free</div><div class="billing-plan-price">$0</div><p class="billing-plan-desc">For trying Lucas and light personal workflows.</p><ul class="billing-plan-features"><li>1,000 Operations / month</li><li>1 Computer</li><li>1 AI account</li><li>Core Lucas execution</li></ul><button id="billingChooseFree" class="btn secondary" onclick="billingChangePlan('free')">Current</button></div><div id="billingCardPro" class="billing-plan-card"><div class="billing-plan-name">Pro</div><div class="billing-plan-price"><span id="billingProPrice">$9.99</span> <small id="billingProPeriod">/ month</small></div><p class="billing-plan-desc">For regular personal automation on multiple computers.</p><ul class="billing-plan-features"><li>25,000 Operations / month</li><li>3 Computers</li><li>1 AI account</li><li>Full Lucas execution</li></ul><button id="billingChoosePro" class="btn primary" onclick="billingChangePlan('pro')">Upgrade</button></div><div id="billingCardProPlus" class="billing-plan-card is-featured"><span class="billing-plan-tag">BEST VALUE</span><div class="billing-plan-name">Pro+</div><div class="billing-plan-price"><span id="billingProPlusPrice">$19.99</span> <small id="billingProPlusPeriod">/ month</small></div><p class="billing-plan-desc">For heavier workflows and users who need expandable capacity.</p><ul class="billing-plan-features"><li>100,000 Operations / month</li><li>6 Computers</li><li>3 AI accounts</li><li>Expansion Pack access</li></ul><button id="billingChooseProPlus" class="btn primary" onclick="billingChangePlan('pro_plus')">Upgrade</button></div></div><div class="card billing-expansion-card"><div style="display:flex;justify-content:space-between;align-items:center;gap:14px;flex-wrap:wrap"><div><h3 style="margin-bottom:5px">Expansion Pack · <span id="billingExpansionPrice">$14.99/mo</span></h3><p class="muted" style="margin:0">Pro+ only · +100,000 Operations · +6 Computers · +1 AI account per pack</p></div><div id="billingExpansion"></div></div></div><div class="card billing-payment-card"><div><h3 style="margin-bottom:5px">Billing & payment</h3><p class="muted" style="margin:0">Update your payment method, view invoices, cancel, or manage subscription billing.</p></div><button id="billingManage" class="btn secondary" onclick="billingPortal()">Manage billing & payment</button></div></div>'''
